#![no_main]

use libfuzzer_sys::fuzz_target;
use sw_crypto::{decrypt_with_asymmetric, AsymmetricKey};

const GO_PKCS8_HEX: &str = "";

fn hex_to_vec(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .filter_map(|i| u8::from_str_radix(&s[i..i + 2], 16).ok())
        .collect()
}

fuzz_target!(|data: &[u8]| {
    let pkcs8 = hex_to_vec(GO_PKCS8_HEX);
    if let Ok(key) = AsymmetricKey::from_pkcs8(&pkcs8) {
        let _ = decrypt_with_asymmetric(data, &key);
    }
});
